    /// Drive a request that expects a response and return what the extension
    /// received, plus whether a prompt card was raised.
    fn ask_ui_query(
        method: &str,
        payload: serde_json::Value,
    ) -> (Option<serde_json::Value>, bool, usize) {
        let (_agent_tx, rx) = mpsc::channel();
        let (ext_tx, ext_rx) = mpsc::channel::<ExtensionUiResponse>();
        let model = PiFtuiModel::new(rx).with_ext_reply_channel(ext_tx);
        let mut sim = ProgramSimulator::new(model);
        sim.init();
        let before = sim.model().transcript.len();
        sim.send(PiFtuiMsg::Agent(PiMsg::ExtensionUiRequest(ext_request(
            "q", method, payload,
        ))));
        let reply = ext_rx.try_recv().ok().and_then(|r| r.value);
        (
            reply,
            sim.model().active_ext.is_some(),
            sim.model().transcript.len() - before,
        )
    }

    /// `ctx.ui.custom` components (usage bars, settings panels, the arcade
    /// games) poll `custom` every 16 ms for keys and stream their frames as
    /// `setWidget`. On this stack each poll became a prompt card and each
    /// frame a transcript line, so a component never received a key.
    #[test]
    fn custom_components_get_frames_and_keys_and_ctrl_c_closes_them() {
        let (_agent_tx, rx) = mpsc::channel();
        let (ext_tx, ext_rx) = mpsc::channel::<ExtensionUiResponse>();
        let model = PiFtuiModel::new(rx).with_ext_reply_channel(ext_tx);
        let mut sim = ProgramSimulator::new(model);
        sim.init();
        let before = sim.model().transcript.len();
        let poll = |sim: &mut ProgramSimulator<PiFtuiModel>, mode: &str| {
            sim.send(PiFtuiMsg::Agent(PiMsg::ExtensionUiRequest(ext_request(
                "poll",
                "custom",
                serde_json::json!({"mode": mode, "widgetKey": EXT_CUSTOM_OVERLAY_KEY}),
            ))));
            ext_rx
                .try_recv()
                .expect("poll answered")
                .value
                .expect("poll value")
        };
        let frame = |sim: &mut ProgramSimulator<PiFtuiModel>, payload: serde_json::Value| {
            let mut payload = payload;
            if let Some(fields) = payload.as_object_mut() {
                fields.insert(
                    String::from("widgetKey"),
                    serde_json::json!(EXT_CUSTOM_OVERLAY_KEY),
                );
            }
            send_ui_effect(sim, "setWidget", payload);
        };

        sim.inject_event(Event::Resize {
            width: 64,
            height: 20,
        });
        let first = poll(&mut sim, "poll");
        assert_eq!(first.get("width"), Some(&serde_json::json!(60)), "{first}");
        assert!(
            first.get("key").is_none() && first.get("closed").is_none(),
            "{first}"
        );
        assert!(
            sim.model().active_ext.is_none(),
            "a poll is not a prompt card"
        );

        frame(
            &mut sim,
            serde_json::json!({"title": "Tetris", "lines": ["\u{1b}[31mscore 10\u{1b}[0m", "next: L"]}),
        );
        assert_eq!(
            sim.model().transcript.len(),
            before,
            "frames are not transcript lines"
        );
        let rendered = buffer_text(sim.capture_frame(60, 12), 60, 12);
        assert!(
            rendered.contains("Tetris")
                && rendered.contains("score 10")
                && rendered.contains("next: L"),
            "{rendered:?}"
        );

        // Keys typed while it is open reach the component, in order.
        sim.inject_event(key(KeyCode::Left, Modifiers::empty()));
        sim.inject_event(key(KeyCode::Char('q'), Modifiers::empty()));
        assert!(sim.model().input.is_empty(), "keys do not reach the editor");
        assert_eq!(
            poll(&mut sim, "poll").get("key"),
            Some(&serde_json::json!("\u{1b}[D"))
        );
        assert_eq!(
            poll(&mut sim, "poll").get("key"),
            Some(&serde_json::json!("q"))
        );

        // Ctrl+C closes it. A frame still in flight does not reopen it, and
        // the next poll tells the component to stop.
        sim.inject_event(key(KeyCode::Char('c'), Modifiers::CTRL));
        frame(&mut sim, serde_json::json!({"lines": ["late frame"]}));
        let rendered = buffer_text(sim.capture_frame(60, 12), 60, 12);
        assert!(!rendered.contains("late frame"), "{rendered:?}");
        assert!(
            sim.model().error_banner.is_none(),
            "closing a component is not the first press of an exit"
        );
        assert_eq!(
            poll(&mut sim, "poll").get("closed"),
            Some(&serde_json::Value::Bool(true))
        );
        frame(&mut sim, serde_json::json!({"clear": true, "lines": []}));
        assert!(sim.model().ext_custom.is_none());

        // A poll alone opens nothing (`custom` without a component), and the
        // bridge's own close (the component called done) ends it.
        poll(&mut sim, "poll");
        assert!(sim.model().ext_custom.is_none());
        frame(&mut sim, serde_json::json!({"lines": ["again"]}));
        assert!(sim.model().ext_custom.is_some());
        assert_eq!(
            poll(&mut sim, "close").get("closed"),
            Some(&serde_json::Value::Bool(true))
        );
        assert!(sim.model().ext_custom.is_none());
    }

    #[test]
    fn custom_paste_is_atomic_and_preserves_the_selected_recalled_draft() {
        for bracketed in [false, true] {
            let (_tx, mut model) = new_model();
            let (ext_tx, ext_rx) = mpsc::channel();
            let (submit_tx, submit_rx) = mpsc::channel();
            model.record_history("saved\nprompt");
            model.history_back();
            model.input.select_all();
            let model = model
                .with_ext_reply_channel(ext_tx)
                .with_submit_channel(submit_tx);
            let mut sim = ProgramSimulator::new(model);
            sim.init();
            send_ui_effect(
                &mut sim,
                "setWidget",
                serde_json::json!({"widgetKey": EXT_CUSTOM_OVERLAY_KEY, "lines": ["custom input"]}),
            );
            let cursor = sim.model().input.cursor();
            let selection = sim.model().input.selection();
            let undo = sim.model().input.undo_op_count();
            let pasted = "line one\r\n界\tline two\u{3}\n";
            sim.inject_event(Event::Paste(ftui::PasteEvent::new(pasted, bracketed)));
            assert_eq!(sim.model().input.text(), "saved\nprompt");
            assert_eq!(sim.model().input.cursor(), cursor);
            assert_eq!(sim.model().input.selection(), selection);
            assert_eq!(sim.model().input.undo_op_count(), undo);
            assert_eq!(sim.model().history_cursor, Some(0));
            assert!(submit_rx.try_recv().is_err());
            assert!(!sim.model().ext_custom.as_ref().expect("component").closed);
            for expected in [Some(serde_json::json!(pasted)), None] {
                sim.send(PiFtuiMsg::Agent(PiMsg::ExtensionUiRequest(ext_request(
                    "paste-poll",
                    "custom",
                    serde_json::json!({"mode": "poll"}),
                ))));
                let reply = ext_rx
                    .try_recv()
                    .expect("poll response")
                    .value
                    .expect("value");
                assert_eq!(reply.get("key"), expected.as_ref());
                assert!(reply.get("closed").is_none());
            }
            send_ui_effect(
                &mut sim,
                "setWidget",
                serde_json::json!({"widgetKey": EXT_CUSTOM_OVERLAY_KEY, "clear": true}),
            );
            assert_eq!(sim.model().input.text(), "saved\nprompt");
            type_str(&mut sim, "X");
            assert_eq!(sim.model().input.text(), "X", "selection was retained");
            sim.inject_event(key(KeyCode::Char('-'), Modifiers::CTRL));
            assert_eq!(sim.model().input.text(), "saved\nprompt");
        }
    }

    #[test]
    fn custom_paste_respects_queue_capacity_without_splitting_or_empty_eviction() {
        let (_tx, model) = new_model();
        let mut sim = ProgramSimulator::new(model);
        sim.init();
        send_ui_effect(
            &mut sim,
            "setWidget",
            serde_json::json!({"widgetKey": EXT_CUSTOM_OVERLAY_KEY, "lines": ["custom input"]}),
        );
        sim.model_mut()
            .ext_custom
            .as_mut()
            .expect("component")
            .keys
            .extend((0..EXT_CUSTOM_MAX_KEYS).map(|index| format!("key-{index}")));
        sim.inject_event(Event::Paste(ftui::PasteEvent::new("", true)));
        let overlay = sim.model().ext_custom.as_ref().expect("component");
        assert_eq!(overlay.keys.len(), EXT_CUSTOM_MAX_KEYS);
        assert_eq!(overlay.keys.front().map(String::as_str), Some("key-0"));
        let pasted = "first\r\nsecond\u{3}";
        sim.inject_event(Event::Paste(ftui::PasteEvent::new(pasted, true)));
        let overlay = sim.model().ext_custom.as_ref().expect("component");
        assert_eq!(overlay.keys.len(), EXT_CUSTOM_MAX_KEYS);
        assert_eq!(overlay.keys.front().map(String::as_str), Some("key-1"));
        assert_eq!(overlay.keys.back().map(String::as_str), Some(pasted));
        assert!(!overlay.closed);
        assert!(sim.model().input.is_empty());
    }

    #[test]
    fn picker_and_question_pastes_keep_precedence_over_a_custom_component() {
        for owner in ["picker", "ask", "extension"] {
            let (_tx, mut model) = new_model();
            model.input.set_text("saved\nprompt");
            let mut sim = ProgramSimulator::new(model);
            sim.init();
            send_ui_effect(
                &mut sim,
                "setWidget",
                serde_json::json!({"widgetKey": EXT_CUSTOM_OVERLAY_KEY, "lines": ["custom input"]}),
            );
            match owner {
                "picker" => sim.send(PiFtuiMsg::Agent(PiMsg::MessagePicker {
                    fork: false,
                    messages: vec![(String::from("choice"), String::from("entry"))],
                })),
                "ask" => sim.send(PiFtuiMsg::Agent(PiMsg::AskUiRequest(ask_request(
                    "paste-question",
                    vec![question("Choose?", &["A", "B"], false)],
                )))),
                _ => sim.send(PiFtuiMsg::Agent(PiMsg::ExtensionUiRequest(ext_request(
                    "paste-question",
                    "input",
                    serde_json::json!({"title": "Reply"}),
                )))),
            }
            assert!(!sim.model().custom_overlay_open());
            sim.inject_event(Event::Paste(ftui::PasteEvent::new("choice\r\nnext", true)));
            assert!(
                sim.model()
                    .ext_custom
                    .as_ref()
                    .expect("component")
                    .keys
                    .is_empty()
            );
            if owner == "picker" {
                assert_eq!(
                    sim.model().picker.as_ref().expect("picker").query,
                    "choicenext"
                );
                assert_eq!(sim.model().input.text(), "saved\nprompt");
            } else {
                assert_eq!(sim.model().input.text(), "choice\nnext");
                assert_eq!(
                    sim.model().card_draft_snapshot.as_deref(),
                    Some("saved\nprompt")
                );
            }
            sim.inject_event(key(KeyCode::Escape, Modifiers::empty()));
            assert_eq!(sim.model().input.text(), "saved\nprompt");
            assert!(sim.model().custom_overlay_open());
            sim.inject_event(Event::Paste(ftui::PasteEvent::new("back to component", true)));
            assert_eq!(
                sim.model()
                    .ext_custom
                    .as_ref()
                    .expect("component")
                    .keys
                    .front()
                    .map(String::as_str),
                Some("back to component")
            );
            assert_eq!(sim.model().input.text(), "saved\nprompt");
        }
    }

    #[test]
    fn get_editor_text_answers_the_extension_instead_of_prompting_the_user() {
        // Before this, a query expecting a response fell through to a prompt
        // card: the user saw a question nobody asked, and the extension got
        // whatever they typed rather than the editor's contents.
        let (reply, card, _) = ask_ui_query("getEditorText", serde_json::json!({}));
        assert_eq!(reply, Some(serde_json::Value::String(String::new())));
        assert!(!card, "a query must not raise a prompt card");
    }

    #[test]
    fn theme_queries_report_what_this_stack_actually_supports() {
        let (all, card, _) = ask_ui_query("getAllThemes", serde_json::json!({}));
        assert!(!card);
        let names: Vec<String> = all
            .expect("themes")
            .as_array()
            .expect("array")
            .iter()
            .filter_map(|entry| entry["name"].as_str().map(str::to_string))
            .collect();
        // User themes on this machine may follow the built-ins.
        assert!(
            names.starts_with(&["dark", "light", "solarized"].map(String::from)),
            "{names:?}"
        );

        let (one, _, _) = ask_ui_query("getTheme", serde_json::json!({"name": "light"}));
        assert!(one.is_some_and(|value| !value.is_null()), "light resolves");
        let (solarized, _, _) = ask_ui_query("getTheme", serde_json::json!({"name": "solarized"}));
        assert!(
            solarized.is_some_and(|value| !value.is_null()),
            "solarized resolves"
        );

        let (missing, _, _) = ask_ui_query("getTheme", serde_json::json!({"name": "nope"}));
        assert_eq!(
            missing,
            Some(serde_json::Value::Null),
            "an unknown theme is null"
        );
    }

    #[test]
    fn set_theme_applies_and_reports_whether_it_took() {
        let (applied, card, entries) =
            ask_ui_query("setTheme", serde_json::json!({"name": "light"}));
        assert_eq!(applied, Some(serde_json::Value::Bool(true)));
        assert!(!card);
        assert_eq!(entries, 1, "applying a theme announces it");

        let (refused, _, _) = ask_ui_query("setTheme", serde_json::json!({"name": "nope"}));
        assert_eq!(
            refused,
            Some(serde_json::Value::Bool(false)),
            "an unsupported theme reports false rather than pretending"
        );
    }

    #[test]
    fn an_effect_this_stack_cannot_carry_out_still_prints() {
        // An effect this stack does not know still prints, which is better
        // than swallowing it.
        let (_tx, model) = new_model();
        let mut sim = ProgramSimulator::new(model);
        sim.init();
        let before = sim.model().transcript.len();

        send_ui_effect(&mut sim, "frobnicate", serde_json::json!({"text": "a"}));
        let added = &sim.model().transcript[before..];
        assert_eq!(added.len(), 1, "an unknown effect should still surface");
        assert_eq!(added[0].role, EntryRole::System);
    }

    /// `ui.setWidget` (usage meters, plan trackers, MCP server lists) printed
    /// every update as a transcript line here. OMP keeps one widget per key
    /// above the editor.
    #[test]
    fn widgets_show_above_the_editor_per_key_instead_of_printing() {
        let (_tx, model) = new_model();
        let mut sim = ProgramSimulator::new(model);
        sim.init();
        let before = sim.model().transcript.len();
        let body = sim.model().body_height();

        send_ui_effect(
            &mut sim,
            "setWidget",
            serde_json::json!({"widgetKey": "b-usage", "lines": ["usage 40%"]}),
        );
        send_ui_effect(
            &mut sim,
            "set_widget",
            serde_json::json!({"widget_key": "a-cost", "content": "\u{1b}[32mcost $0.12\u{1b}[0m"}),
        );
        assert_eq!(
            sim.model().transcript.len(),
            before,
            "widgets are not transcript lines"
        );
        assert_eq!(sim.model().body_height(), body - 2);
        let rendered = buffer_text(sim.capture_frame(60, 24), 60, 24);
        let cost = rendered.find("cost $0.12");
        let usage = rendered.find("usage 40%");
        assert!(
            cost.is_some() && usage.is_some() && cost < usage,
            "widgets show in key order: {rendered:?}"
        );

        // An update replaces that key's widget.
        send_ui_effect(
            &mut sim,
            "setWidget",
            serde_json::json!({"widgetKey": "b-usage", "lines": ["usage 55%"]}),
        );
        let rendered = buffer_text(sim.capture_frame(60, 24), 60, 24);
        assert!(
            rendered.contains("usage 55%") && !rendered.contains("usage 40%"),
            "{rendered:?}"
        );

        // A tall widget is cut at ten lines with a marker, as OMP cuts it.
        sim.inject_event(Event::Resize {
            width: 60,
            height: 80,
        });
        let tall: Vec<String> = (1..=12).map(|n| format!("row {n}")).collect();
        send_ui_effect(
            &mut sim,
            "setWidget",
            serde_json::json!({"widgetKey": "c-tall", "lines": tall}),
        );
        let rendered = buffer_text(sim.capture_frame(60, 80), 60, 80);
        assert!(
            rendered.contains("row 10")
                && !rendered.contains("row 11")
                && rendered.contains("... (widget truncated)"),
            "{rendered:?}"
        );

        // A widget set without lines (`setWidget(key, undefined)`) removes
        // only that key.
        send_ui_effect(
            &mut sim,
            "setWidget",
            serde_json::json!({"widgetKey": "b-usage"}),
        );
        send_ui_effect(
            &mut sim,
            "setWidget",
            serde_json::json!({"widgetKey": "c-tall", "lines": []}),
        );
        let rendered = buffer_text(sim.capture_frame(60, 80), 60, 80);
        assert!(
            rendered.contains("cost $0.12") && !rendered.contains("usage 55%"),
            "{rendered:?}"
        );
        assert_eq!(sim.model().widget_rows(), 1);
        assert_eq!(sim.model().transcript.len(), before);
    }

    /// `ui.notify(message, level)` printed every notice as
    /// "[ext] Extension message", so an extension's error read as info.
    #[test]
    fn extension_notices_keep_their_level() {
        let (_tx, model) = new_model();
        let mut sim = ProgramSimulator::new(model);
        sim.init();
        let before = sim.model().transcript.len();

        send_ui_effect(
            &mut sim,
            "notify",
            serde_json::json!({"message": "Build failed", "level": "error"}),
        );
        send_ui_effect(
            &mut sim,
            "notify",
            serde_json::json!({"message": "Disk low", "notifyType": "warning"}),
        );
        send_ui_effect(
            &mut sim,
            "notify",
            serde_json::json!({"title": "Done", "message": "\u{1b}[32msaved\u{1b}[0m"}),
        );
        let added: Vec<(EntryRole, &str)> = sim.model().transcript[before..]
            .iter()
            .map(|entry| (entry.role, entry.text.as_str()))
            .collect();
        assert_eq!(
            added,
            [
                (EntryRole::Error, "[demo-ext] Build failed"),
                (EntryRole::System, "[demo-ext] warning: Disk low"),
                (EntryRole::System, "[demo-ext] Done saved"),
            ]
        );
    }

    #[test]
    fn extension_reply_disconnect_cancels_pending_and_rejects_new_prompts() {
        let (agent_tx, agent_rx) = mpsc::channel();
        let handler = FtuiExtensionUiHandler::new(agent_tx);
        let (pending_tx, mut pending_rx) = asupersync::channel::oneshot::channel();
        handler
            .pending
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .insert(String::from("startup-prompt"), pending_tx);
        let (ext_reply_tx, ext_reply_rx) = mpsc::channel::<ExtensionUiResponse>();
        drop(ext_reply_tx);

        assert!(matches!(
            poll_ext_reply(&handler, &ext_reply_rx),
            ExtReplyPoll::Disconnected
        ));
        assert!(
            handler
                .pending
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .is_empty(),
            "disconnect must drain every outstanding prompt"
        );

        let runtime = asupersync::runtime::RuntimeBuilder::current_thread()
            .build()
            .expect("runtime");
        let cancelled = runtime
            .block_on(async {
                let cx = crate::agent_cx::AgentCx::for_current_or_request();
                pending_rx.recv(cx.cx()).await
            })
            .expect("pending prompt receives cancellation");
        assert_eq!(cancelled.id, "startup-prompt");
        assert!(cancelled.cancelled);

        let mut late_request = ext_request(
            "late-prompt",
            "confirm",
            serde_json::json!({"title": "Too late?"}),
        );
        late_request.timeout_ms = Some(10);
        let rejected = runtime
            .block_on(crate::sdk::ExtensionUiHandler::request_ui(
                &handler,
                late_request,
            ))
            .expect("closed UI returns a typed response")
            .expect("closed UI returns cancellation rather than absence");
        assert_eq!(rejected.id, "late-prompt");
        assert!(rejected.cancelled);
        assert!(
            agent_rx.try_recv().is_err(),
            "closed reply channel must reject new prompts before UI dispatch"
        );
    }

    #[test]
    fn ftui_extension_handler_notification_never_waits_for_reply() {
        asupersync::test_utils::run_test(|| async {
            let (agent_tx, agent_rx) = mpsc::channel();
            let handler = FtuiExtensionUiHandler::new(agent_tx);
            let notification = ext_request(
                "notify-1",
                "notify",
                serde_json::json!({"title": "Complete", "message": "Build finished"}),
            );

            let outcome = asupersync::time::timeout(
                asupersync::time::wall_now(),
                std::time::Duration::from_millis(20),
                crate::sdk::ExtensionUiHandler::request_ui(&handler, notification),
            )
            .await
            .expect("notification must not wait on the response timeout")
            .expect("notification dispatch succeeds");

            assert!(outcome.is_none(), "notification has no response contract");
            assert!(
                handler
                    .pending
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner)
                    .is_empty(),
                "notification must not allocate a pending waiter"
            );
            assert!(matches!(
                agent_rx.try_recv(),
                Ok(PiMsg::ExtensionUiRequest(request)) if request.id == "notify-1"
            ));
        });
    }

    #[test]
    fn dropping_ftui_extension_request_releases_pending_entry() {
        asupersync::test_utils::run_test(|| async {
            let (agent_tx, agent_rx) = mpsc::channel();
            let handler = FtuiExtensionUiHandler::new(agent_tx);
            let request = ext_request(
                "cancelled-ftui-request",
                "confirm",
                serde_json::json!({"title": "Cancel me"}),
            );
            let mut attempt = Box::pin(crate::sdk::ExtensionUiHandler::request_ui(
                &handler, request,
            ));
            assert!(futures::poll!(attempt.as_mut()).is_pending());
            assert!(matches!(
                agent_rx.try_recv(),
                Ok(PiMsg::ExtensionUiRequest(request))
                    if request.id == "cancelled-ftui-request"
            ));
            assert_eq!(
                handler
                    .pending
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner)
                    .len(),
                1
            );

            drop(attempt);

            assert!(
                handler
                    .pending
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner)
                    .is_empty(),
                "cancelling the outer future must release its pending lease"
            );
        });
    }

    #[test]
    fn ask_reply_disconnect_closes_picker_surface() {
        let tool = crate::ask::AskTool::new(crate::ask::AskPolicy::Error);
        let (ui_tx, _ui_rx) = asupersync::channel::mpsc::channel::<AskUiRequest>(4);
        tool.install_channel_ui(ui_tx);
        let current_ask = Arc::new(Mutex::new(Some(tool.clone())));
        let (reply_tx, reply_rx) = mpsc::channel::<AskUiReply>();
        drop(reply_tx);

        assert!(matches!(
            poll_ask_reply(&current_ask, &reply_rx),
            AskReplyPoll::Disconnected
        ));

        let runtime = asupersync::runtime::RuntimeBuilder::current_thread()
            .build()
            .expect("runtime");
        let result = runtime.block_on(async {
            asupersync::time::timeout(
                asupersync::time::wall_now(),
                std::time::Duration::from_millis(20),
                crate::tools::Tool::execute(
                    &tool,
                    "ask-after-disconnect",
                    serde_json::json!({
                        "questions": [{
                            "question": "Too late?",
                            "options": [{"label": "A"}, {"label": "B"}]
                        }]
                    }),
                    None,
                ),
            )
            .await
        });
        let error = result
            .expect("closed picker must reject before the short mutation guard expires")
            .expect_err("closed picker must reject later cards");
        assert!(
            error.to_string().contains("picker surface closed"),
            "{error}"
        );
    }

