    /// `/reload` re-reads resources and keeps the conversation: an extension
    /// edited on disk after launch is replaced by its new version, and the
    /// session (id and messages) is the same one. An unsaved in-memory
    /// conversation is refused, not dropped.
    #[test]
    #[allow(clippy::too_many_lines)]
    fn reload_picks_up_an_edited_extension_and_keeps_the_conversation() {
        let runtime = asupersync::runtime::RuntimeBuilder::new()
            .build()
            .expect("runtime");
        let runtime_handle = runtime.handle();
        let cwd = tempfile::tempdir().expect("cwd");
        let sessions = tempfile::tempdir().expect("sessions");
        let extension = cwd.path().join("reload-probe.mjs");
        let write_extension = |command: &str| {
            std::fs::write(
                &extension,
                format!(
                    "export default function init(pi) {{\n\
                     pi.registerCommand(\"{command}\", {{ description: \"probe\", handler: async (args) => ({{command: \"{command}\", args}}) }});\n\
                     }}\n"
                ),
            )
            .expect("write extension");
        };
        write_extension("Plan");

        let (agent_tx, agent_rx) = mpsc::channel::<PiMsg>();
        let registry: ExtensionCommandRegistry = Arc::default();
        let ext_handler = Arc::new(FtuiExtensionUiHandler {
            command_registry: Arc::downgrade(&registry),
            ..FtuiExtensionUiHandler::new(agent_tx.clone())
        });
        let (_model_tx, model_rx) = mpsc::channel();
        let (submit_tx, submit_rx) = mpsc::channel();
        let mut model = PiFtuiModel::new(model_rx)
            .with_submit_channel(submit_tx)
            .with_extension_command_registry(registry);
        let template = resume_template_from(&crate::sdk::SessionOptions {
            provider: Some(String::from("openai")),
            model: Some(String::from("gpt-4o")),
            api_key: Some(String::from("dummy-key")),
            working_directory: Some(cwd.path().to_path_buf()),
            workspace_trusted: true,
            session_dir: Some(sessions.path().to_path_buf()),
            extension_paths: vec![extension.clone()],
            ..crate::sdk::SessionOptions::default()
        });
        let current_ask: CurrentAsk = Arc::new(Mutex::new(None));

        runtime.block_on(async move {
            let mut handle = crate::sdk::create_agent_session_deferred_mcp(replacement_options(
                &template,
                &ext_handler,
                &runtime_handle,
            ))
            .await
            .expect("create session");
            assert!(
                handle
                    .extension_manager()
                    .is_some_and(|manager| manager.has_command("Plan"))
            );
            ext_handler.install_command_registry(&handle);
            let mut catalog = AutocompleteCatalog::default();
            refresh_extension_commands(&handle, &mut catalog, &agent_tx);
            assert!(
                catalog
                    .extension_commands
                    .iter()
                    .any(|entry| entry.name == "Plan")
            );
            assert!(model.route_slash_command("/PLAN Keep  These ARGs"));
            let UiCommand::RegisteredExtensionCommand { name, args } =
                submit_rx.try_recv().expect("extension route")
            else {
                panic!("registered /plan must precede the built-in");
            };
            run_extension_command(&handle, cwd.path(), &name, &args, true, &agent_tx).await;
            assert!(
                agent_rx.try_iter().any(|message| {
                    matches!(message, PiMsg::SystemNote(text)
                        if text.contains(r#""command":"Plan""#)
                            && text.contains(r#""args":"Keep  These ARGs""#))
                }),
                "the real registered handler must receive its original arguments"
            );
            assert!(model.route_slash_command("/plan stale-before-reload"));
            let stale = submit_rx.try_recv().expect("queued before reload");

            // A saved conversation with a newer pending row. Reload must
            // flush it even when ordinary shutdown uses throughput mode, and
            // open the replacement only after that flush reaches disk.
            let (session_id, session_path) = {
                let store = handle.session_store();
                let cx = crate::agent_cx::AgentCx::for_request();
                let mut session = store.lock(cx.cx()).await.expect("session lock");
                session.append_message(crate::session::SessionMessage::User {
                    content: crate::model::UserContent::Text(String::from("keep me")),
                    timestamp: Some(0),
                });
                session.save().await.expect("save session");
                session.set_autosave_durability_mode(
                    crate::session::AutosaveDurabilityMode::Throughput,
                );
                session.append_message(crate::session::SessionMessage::User {
                    content: crate::model::UserContent::Text(String::from("keep pending too")),
                    timestamp: Some(1),
                });
                assert_eq!(session.autosave_metrics().pending_mutations, 1);
                (
                    session.header.id.clone(),
                    session.path.clone().expect("saved session path"),
                )
            };

            // A failed default-mode save must leave the old runtime live and
            // must not announce a completed reload. Repairing the destination
            // lets the same handle retry with every queued row still present.
            let original_store = handle.session_store();
            let blocked = sessions.path().join("directory-not-session.jsonl");
            std::fs::create_dir(&blocked).expect("block reload save");
            {
                let mut session = original_store.try_lock().expect("current session");
                session.path = Some(blocked);
                session.set_autosave_durability_mode(
                    crate::session::AutosaveDurabilityMode::Balanced,
                );
            }
            reload_session_command(
                &template,
                &mut handle,
                &current_ask,
                &ext_handler,
                &agent_tx,
                &runtime_handle,
            )
            .await
            .expect("a refused reload keeps the driver running");
            assert!(Arc::ptr_eq(&original_store, &handle.session_store()));
            let refused = agent_rx.try_iter().collect::<Vec<_>>();
            assert!(refused.iter().any(|message| matches!(
                message,
                PiMsg::AgentError(text) if text.contains("failed to flush session autosave")
            )));
            assert!(!refused.iter().any(|message| matches!(
                message,
                PiMsg::System(text) if text.starts_with("Reloaded")
            )));
            run_extension_command(&handle, cwd.path(), "Plan", "still live", true, &agent_tx).await;
            assert!(agent_rx.try_iter().any(|message| matches!(
                message,
                PiMsg::SystemNote(text) if text.contains(r#""args":"still live""#)
            )), "refused preflight must not stop the old extension runtime");
            {
                let mut session = original_store.try_lock().expect("retryable session");
                assert_eq!(session.header.id, session_id);
                assert_eq!(session.autosave_metrics().pending_mutations, 1);
                session.path = Some(session_path.clone());
                session.set_autosave_durability_mode(
                    crate::session::AutosaveDurabilityMode::Throughput,
                );
            }
            let old_origin = handle
                .session()
                .session_action_admission_gate()
                .capture_origin();
            let old_extension_session = handle
                .extension_manager()
                .expect("current extension manager")
                .session_handle()
                .expect("current extension session adapter");

            write_extension("status");
            reload_session_command(
                &template,
                &mut handle,
                &current_ask,
                &ext_handler,
                &agent_tx,
                &runtime_handle,
            )
            .await
            .expect("reload");

            let stale_error = old_extension_session
                .append_custom_entry(
                    "pre-reload-action".to_string(),
                    None,
                    Some(old_origin),
                )
                .await
                .expect_err("an action captured before replacement cannot mutate the old store");
            assert!(stale_error.to_string().contains("active Session changed"));
            assert!(original_store.try_lock().unwrap().entries.iter().all(|entry| !matches!(
                entry,
                crate::session::SessionEntry::Custom(custom)
                    if custom.custom_type == "pre-reload-action"
            )));
            let manager = handle.extension_manager().expect("extensions after reload");
            assert!(
                manager.has_command("status"),
                "the edited extension must load"
            );
            assert!(!manager.has_command("Plan"), "the old version must be gone");
            // No resource source and no catalog delivery: committed replacement
            // alone must update routing, including newly shadowed built-ins.
            assert!(model.route_slash_command("/status after reload"));
            let UiCommand::RegisteredExtensionCommand { name, args } =
                submit_rx.try_recv().expect("new live extension route")
            else {
                panic!("reloaded /status must precede the built-in");
            };
            run_extension_command(&handle, cwd.path(), &name, &args, true, &agent_tx).await;
            assert!(model.route_slash_command("/plan status"));
            assert_eq!(
                submit_rx
                    .try_recv()
                    .expect("removed override restores built-in"),
                UiCommand::Plan {
                    action: String::from("status")
                }
            );
            refresh_extension_commands(&handle, &mut catalog, &agent_tx);
            assert!(
                catalog
                    .extension_commands
                    .iter()
                    .any(|entry| entry.name == "status")
            );
            assert!(
                !catalog
                    .extension_commands
                    .iter()
                    .any(|entry| entry.name == "Plan")
            );
            let (id, kept, kept_pending) = handle
                .with_session(|session| {
                    let messages = session.to_messages_for_current_path();
                    let contains = |expected: &str| messages
                        .iter()
                        .any(|message| matches!(
                            message,
                            crate::model::Message::User(user)
                                if matches!(&user.content, crate::model::UserContent::Text(text) if text == expected)
                        ));
                    (session.header.id.clone(), contains("keep me"), contains("keep pending too"))
                })
                .await
                .expect("session snapshot");
            assert_eq!(id, session_id, "reload keeps the same session");
            assert!(kept, "reload keeps the conversation");
            assert!(kept_pending, "reload includes mutations flushed during replacement preflight");
            let reopened = crate::session::Session::open(
                session_path.to_str().expect("session path"),
            )
            .await
            .expect("reopen reloaded session");
            assert!(reopened.to_messages_for_current_path().iter().any(|message| matches!(
                message,
                crate::model::Message::User(user)
                    if matches!(&user.content, crate::model::UserContent::Text(text) if text == "keep pending too")
            )), "reload durably saves throughput-mode pending rows");
            let replies = agent_rx.try_iter().collect::<Vec<_>>();
            assert!(
                replies
                    .iter()
                    .any(|msg| matches!(msg, PiMsg::System(text) if text.starts_with("Reloaded"))),
                "the user is told the reload happened"
            );
            assert!(
                replies.iter().any(|message| {
                    matches!(message, PiMsg::SystemNote(text)
                        if text.contains(r#""command":"status""#)
                            && text.contains(r#""args":"after reload""#))
                }),
                "the replacement runtime executes the newly registered command"
            );
            let UiCommand::RegisteredExtensionCommand { name, args } = stale else {
                panic!("queued registration retains strict dispatch");
            };
            run_extension_command(&handle, cwd.path(), &name, &args, true, &agent_tx).await;
            let stale_replies = agent_rx.try_iter().collect::<Vec<_>>();
            assert!(
                !stale_replies
                    .iter()
                    .any(|message| matches!(message, PiMsg::ToolStart { .. }))
            );
            assert!(
                stale_replies.iter().any(|message| {
                    matches!(message, PiMsg::System(text)
                        if text.starts_with("Extension command '/Plan' is no longer registered"))
                }),
                "an obsolete queued command must be refused, not reinterpreted"
            );

            // The planted negative: an unsaved in-memory conversation.
            let mut unsaved = crate::sdk::create_agent_session_deferred_mcp({
                let mut options = replacement_options(&template, &ext_handler, &runtime_handle);
                options.no_session = true;
                options
            })
            .await
            .expect("in-memory session");
            {
                let store = unsaved.session_store();
                let cx = crate::agent_cx::AgentCx::for_request();
                let mut session = store.lock(cx.cx()).await.expect("session lock");
                session.path = None;
                session.append_message(crate::session::SessionMessage::User {
                    content: crate::model::UserContent::Text(String::from("unsaved")),
                    timestamp: Some(0),
                });
            }
            let unsaved_id = unsaved
                .with_session(|session| session.header.id.clone())
                .await
                .expect("id");
            reload_session_command(
                &template,
                &mut unsaved,
                &current_ask,
                &ext_handler,
                &agent_tx,
                &runtime_handle,
            )
            .await
            .expect("refusal is not a driver failure");
            assert_eq!(
                unsaved
                    .with_session(|session| session.header.id.clone())
                    .await
                    .expect("id"),
                unsaved_id,
                "an unsaved conversation must not be replaced"
            );
            assert!(
                agent_rx
                    .try_iter()
                    .any(|msg| matches!(msg, PiMsg::AgentError(text) if text.contains("not saved"))),
                "the refusal is reported"
            );
            let _ = unsaved.shutdown_owned_resources().await;
            let _ = handle.shutdown_owned_resources().await;
        });
    }

    fn unroutable_btw_client() -> Arc<crate::btw::BtwClient> {
        Arc::new(crate::btw::BtwClient::new(
            Arc::new(
                crate::providers::openai::OpenAIProvider::new("btw-fixture")
                    .with_base_url("http://127.0.0.1:1/v1"),
            ),
            None,
        ))
    }

    /// OMP's /btw on the default stack: idle, it goes to the driver (which
    /// adds vault-transformed context); without a smol model it is refused
    /// before anything is sent.
    #[test]
    fn slash_btw_routes_when_a_smol_client_exists_and_refuses_otherwise() {
        let (_agent_tx, rx) = mpsc::channel();
        let (submit_tx, submit_rx) = mpsc::channel::<UiCommand>();
        let mut model = PiFtuiModel::new(rx)
            .with_submit_channel(submit_tx)
            .with_btw_client(Some(unroutable_btw_client()));
        model.displayed_session_id = Some(String::from("btw-session"));
        let mut sim = ProgramSimulator::new(model);
        sim.init();
        type_str(&mut sim, "/btw what is a monad");
        sim.inject_event(key(KeyCode::Enter, Modifiers::empty()));
        assert_eq!(
            submit_rx.try_recv().expect("routed"),
            UiCommand::Btw {
                question: String::from("what is a monad"),
                title: None,
                owner_session_id: String::from("btw-session"),
            }
        );

        let (_agent_tx, rx) = mpsc::channel();
        let (submit_tx, submit_rx) = mpsc::channel::<UiCommand>();
        let mut sim = ProgramSimulator::new(PiFtuiModel::new(rx).with_submit_channel(submit_tx));
        sim.init();
        type_str(&mut sim, "/btw anything");
        sim.inject_event(key(KeyCode::Enter, Modifiers::empty()));
        assert!(
            submit_rx.try_recv().is_err(),
            "no smol model: nothing is sent"
        );
        assert!(
            sim.model()
                .transcript
                .iter()
                .any(|entry| entry.text == BTW_UNAVAILABLE),
            "the refusal says why"
        );
    }

    /// Mid-turn questions stay ephemeral and wait in the command lane until
    /// the driver can screen them against the live vault. The UI must never
    /// spawn an unseeded auxiliary request while the Agent is borrowed.
    #[test]
    fn slash_btw_mid_turn_waits_for_live_privacy_projection() {
        let slot: TurnControlSlot = Arc::default();
        let (_agent_tx, rx) = mpsc::channel();
        let (submit_tx, submit_rx) = mpsc::channel::<UiCommand>();
        let mut model = PiFtuiModel::new(rx)
            .with_submit_channel(submit_tx)
            .with_turn_control(slot)
            .with_btw_client(Some(unroutable_btw_client()));
        model.displayed_session_id = Some(String::from("busy-session"));
        let mut sim = ProgramSimulator::new(model);
        sim.init();
        sim.send(PiFtuiMsg::Agent(PiMsg::AgentStart));
        type_str(&mut sim, "/btw quick check");
        sim.inject_event(key(KeyCode::Enter, Modifiers::empty()));
        assert_eq!(
            submit_rx
                .try_recv()
                .expect("question queued for the driver"),
            UiCommand::Btw {
                question: String::from("quick check"),
                title: None,
                owner_session_id: String::from("busy-session"),
            }
        );
        assert!(sim.model().pending_task.is_none());
        assert!(sim.model().input.text().is_empty());
        assert!(
            sim.model().transcript.iter().any(|entry| entry
                .text
                .contains("queued until the current turn finishes")),
            "the note explains when the question will be answered"
        );
    }

    #[test]
    fn side_question_queue_bounds_raw_input_and_requires_session_identity() {
        let (_agent_tx, rx) = mpsc::channel();
        let (submit_tx, submit_rx) = mpsc::channel::<UiCommand>();
        let mut model = PiFtuiModel::new(rx)
            .with_submit_channel(submit_tx)
            .with_btw_client(Some(unroutable_btw_client()));
        model.queue_btw("a question before the session has loaded");
        assert!(submit_rx.try_recv().is_err());
        model.displayed_session_id = Some(String::from("busy-session"));
        model.state = AgentUiState::Working;
        model.queue_btw(&"x".repeat(crate::text_completion::MAX_INPUT_BYTES));
        assert!(submit_rx.try_recv().is_err());
        assert!(model.pending_task.is_none());
        assert!(
            model
                .transcript
                .last()
                .is_some_and(|entry| entry.text.contains("privacy scan budget"))
        );
    }

    fn side_template_resources(content: &str) -> crate::resources::ResourceLoader {
        let mut resources = crate::resources::ResourceLoader::empty(true);
        resources.push_prompt_for_tests(crate::resources::PromptTemplate {
            name: "sitrep".into(),
            description: "Summarize the current work".into(),
            content: content.into(),
            side: true,
            source: "project".into(),
            file_path: std::path::PathBuf::from("sitrep.md"),
        });
        resources
    }

    #[test]
    fn side_templates_route_idle_and_busy_input_outside_the_main_turn() {
        for (busy, follow_up, input, question) in [
            (false, false, "/sitrep", "Summarize"),
            (
                true,
                false,
                "/sitrep \"the retry path\"",
                "Summarize the retry path",
            ),
            (true, true, "/sitrep '$1'", "Summarize $1"),
            (false, false, "/template sitrep", "Summarize"),
            (true, true, "/template /sitrep '$1'", "Summarize $1"),
        ] {
            let (_agent_tx, rx) = mpsc::channel();
            let (submit_tx, submit_rx) = mpsc::channel();
            let mut model = PiFtuiModel::new(rx)
                .with_submit_channel(submit_tx)
                .with_btw_client(Some(unroutable_btw_client()));
            model.steer_resources = Some(side_template_resources("Summarize $ARGUMENTS"));
            model.displayed_session_id = Some("side-owner".into());
            if busy {
                model.state = AgentUiState::Working;
            }
            let state = model.state;
            model.input.set_text(input);
            if busy {
                model.submit_mid_turn(follow_up);
            } else {
                model.submit_input();
            }
            assert_eq!(
                submit_rx.try_recv().expect("side request"),
                UiCommand::Btw {
                    question: question.into(),
                    title: Some(input.into()),
                    owner_session_id: "side-owner".into(),
                }
            );
            assert!(submit_rx.try_recv().is_err(), "no main prompt is submitted");
            assert_eq!(model.state, state);
            assert!(model.pending_task.is_none());
            assert!(model.input.text().is_empty());
            assert_eq!(model.input_history.last().map(String::as_str), Some(input));
            assert!(
                model
                    .transcript
                    .iter()
                    .all(|entry| entry.role == EntryRole::System)
            );
            assert!(
                model
                    .transcript
                    .last()
                    .unwrap()
                    .text
                    .starts_with(&format!("({input})"))
            );
        }
    }

    #[test]
    fn refused_side_templates_keep_the_draft_and_never_fall_back_to_a_prompt() {
        for (content, client, expected) in [
            ("Summarize".into(), false, "unavailable"),
            (" \n ".into(), true, "empty output"),
            (
                "x".repeat(crate::text_completion::MAX_INPUT_BYTES),
                true,
                "privacy scan budget",
            ),
        ] {
            for busy in [false, true] {
                let (_agent_tx, rx) = mpsc::channel();
                let (submit_tx, submit_rx) = mpsc::channel();
                let mut model = PiFtuiModel::new(rx)
                    .with_submit_channel(submit_tx)
                    .with_btw_client(client.then(unroutable_btw_client));
                model.steer_resources = Some(side_template_resources(&content));
                model.displayed_session_id = Some("side-owner".into());
                if busy {
                    model.state = AgentUiState::Working;
                }
                model.input.set_text("/sitrep");
                model.submit_input();
                assert!(submit_rx.try_recv().is_err());
                assert_eq!(model.input.text(), "/sitrep");
                assert!(model.input_history.is_empty());
                assert!(model.transcript.last().unwrap().text.contains(expected));
                assert!(
                    !model
                        .transcript
                        .iter()
                        .any(|entry| entry.role == EntryRole::User)
                );
            }
        }
    }

    #[test]
    fn side_template_metadata_cannot_take_a_native_or_extension_command() {
        let (_agent_tx, rx) = mpsc::channel();
        let (submit_tx, submit_rx) = mpsc::channel();
        let mut model = PiFtuiModel::new(rx)
            .with_submit_channel(submit_tx)
            .with_btw_client(Some(unroutable_btw_client()));
        let mut resources = side_template_resources("Summarize");
        for name in ["help", "stats", "goal", "queue", "switch"] {
            resources.push_prompt_for_tests(crate::resources::PromptTemplate {
                name: name.into(),
                description: String::new(),
                content: "Do not run this".into(),
                side: true,
                source: "project".into(),
                file_path: std::path::PathBuf::from(format!("{name}.md")),
            });
        }
        model.steer_resources = Some(resources);
        model.displayed_session_id = Some("side-owner".into());
        for command in ["/help", "/stats", "/goal", "/queue", "/switch"] {
            assert!(model.side_template_question(command).is_none());
        }
        model.extension_commands = vec![crate::autocomplete::NamedEntry {
            name: "sitrep".into(),
            description: None,
        }];
        model.input.set_text("/sitrep raw arguments");
        model.submit_input();
        assert!(matches!(
            submit_rx.try_recv(),
            Ok(UiCommand::RegisteredExtensionCommand { name, args })
                if name == "sitrep" && args == "raw arguments"
        ));
        model.state = AgentUiState::Working;
        model.input.set_text("/sitrep another argument");
        model.submit_mid_turn(false);
        assert!(submit_rx.try_recv().is_err());
        assert_eq!(model.input.text(), "/sitrep another argument");
    }

    #[derive(Default)]
    struct BtwPrivacyProbe {
        prompts: Mutex<Vec<String>>,
    }

    #[async_trait::async_trait]
    #[allow(clippy::unnecessary_literal_bound)]
    impl crate::provider::Provider for BtwPrivacyProbe {
        fn name(&self) -> &str {
            "btw-privacy"
        }

        fn api(&self) -> &str {
            "test"
        }

        fn model_id(&self) -> &str {
            "btw-privacy"
        }

        async fn stream(
            &self,
            context: &crate::provider::Context<'_>,
            _options: &crate::provider::StreamOptions,
        ) -> crate::error::Result<
            std::pin::Pin<
                Box<
                    dyn futures::Stream<Item = crate::error::Result<crate::model::StreamEvent>>
                        + Send,
                >,
            >,
        > {
            assert!(context.tools.is_empty());
            let crate::model::Message::User(user) = &context.messages[0] else {
                panic!("expected auxiliary user message");
            };
            let crate::model::UserContent::Text(text) = &user.content else {
                panic!("expected auxiliary text projection");
            };
            self.prompts.lock().unwrap().push(text.clone());
            Ok(Box::pin(futures::stream::iter([Ok(
                crate::model::StreamEvent::Done {
                    reason: StopReason::Stop,
                    message: crate::model::AssistantMessage {
                        content: vec![crate::model::ContentBlock::Text(
                            crate::model::TextContent::new("screened side answer"),
                        )],
                        ..Default::default()
                    },
                },
            )])))
        }
    }

    #[test]
    #[allow(clippy::significant_drop_tightening, clippy::too_many_lines)]
    fn side_question_driver_rejects_stale_owners_and_screens_remembered_credentials() {
        let runtime = asupersync::runtime::RuntimeBuilder::current_thread()
            .build()
            .expect("runtime");
        let runtime_handle = runtime.handle();
        runtime.block_on(async {
            let provider = Arc::new(BtwPrivacyProbe::default());
            let known = "previouslyLearnedCredentialValue123456";
            let mut agent = crate::agent::Agent::new(
                provider.clone(),
                crate::tools::ToolRegistry::from_tools(Vec::new()),
                crate::agent::AgentConfig::default(),
            );
            agent
                .secrets_transform_outbound_text(&format!("API_KEY={known}"))
                .unwrap();
            let session = crate::session::Session::in_memory();
            let owner_session_id = session.header.id.clone();
            let session = crate::agent::AgentSession::new(
                agent,
                Arc::new(asupersync::sync::Mutex::new(session)),
                false,
                crate::compaction::ResolvedCompactionSettings::default(),
            );
            let handle = crate::sdk::AgentSessionHandle::from_session_with_listeners(
                session,
                crate::sdk::EventListeners::default(),
            );
            let blocked_client = Arc::new(
                crate::btw::BtwClient::new(provider.clone(), None).with_secrets_settings(Some(
                    &crate::secrets::SecretsSettings {
                        mode: Some(String::from("block")),
                        extra_patterns: None,
                    },
                )),
            );
            let (agent_tx, agent_rx) = mpsc::channel();
            run_btw_command(
                &handle,
                Some(&blocked_client),
                String::from("a clean but stale question"),
                None,
                String::from("replaced-session"),
                &agent_tx,
                &runtime_handle,
            )
            .await;
            assert!(agent_rx.try_recv().is_err());
            run_btw_command(
                &handle,
                Some(&blocked_client),
                format!("Does {known} still work?"),
                None,
                owner_session_id.clone(),
                &agent_tx,
                &runtime_handle,
            )
            .await;
            assert!(matches!(
                agent_rx.try_recv().expect("privacy refusal"),
                PiMsg::SessionSystemNote { message, .. }
                    if message.starts_with("/btw refused:") && !message.contains(known)
            ));
            assert!(provider.prompts.lock().unwrap().is_empty());

            // A permitted request must really reach the same provider, with
            // the remembered value removed even though no assignment remains
            // in the current transcript.
            let redacting_client = Arc::new(crate::btw::BtwClient::new(provider.clone(), None));
            run_btw_command(
                &handle,
                Some(&redacting_client),
                format!("Does {known} still work?"),
                Some(String::from("/sitrep credential status")),
                owner_session_id.clone(),
                &agent_tx,
                &runtime_handle,
            )
            .await;
            let answer = asupersync::time::timeout(
                asupersync::time::wall_now(),
                Duration::from_secs(5),
                async {
                    loop {
                        if let Ok(message) = agent_rx.try_recv() {
                            break message;
                        }
                        asupersync::time::sleep(
                            asupersync::time::wall_now(),
                            Duration::from_millis(1),
                        )
                        .await;
                    }
                },
            )
            .await
            .expect("screened side request completes");
            assert!(matches!(
                answer,
                PiMsg::SessionSystemNote { owner_session_id: owner, message }
                    if owner == owner_session_id
                        && message == "(/sitrep credential status) screened side answer"
            ));
            let prompts = provider.prompts.lock().unwrap();
            assert_eq!(prompts.len(), 1);
            assert!(!prompts[0].contains("/sitrep credential status"));
            assert!(!prompts[0].contains(known));
            assert!(prompts[0].contains("<pi-secret:redacted>"));
            assert!(handle.session().agent.messages().is_empty());
            assert!(
                handle
                    .session()
                    .session
                    .try_lock()
                    .unwrap()
                    .entries
                    .is_empty()
            );
        });
    }

    /// OMP's read-only info commands and aliases route on the default stack;
    /// near-miss tokens still reach extension dispatch.
    #[test]
    fn omp_info_commands_and_aliases_route_to_the_driver() {
        let (_agent_tx, rx) = mpsc::channel();
        let (submit_tx, submit_rx) = mpsc::channel::<UiCommand>();
        let model = PiFtuiModel::new(rx).with_submit_channel(submit_tx);
        let mut sim = ProgramSimulator::new(model);
        sim.init();
        let mut send = |text: &str| {
            type_str(&mut sim, text);
            sim.inject_event(key(KeyCode::Enter, Modifiers::empty()));
            submit_rx.try_recv().expect("routed")
        };
        for (text, expected) in [
            ("/tools", info_commands::InfoCommand::Tools),
            ("/extensions", info_commands::InfoCommand::Extensions),
            ("/skills", info_commands::InfoCommand::Skills),
            ("/dirs", info_commands::InfoCommand::Dirs),
            ("/context", info_commands::InfoCommand::Context),
            ("/todo", info_commands::InfoCommand::Todo),
            ("/jobs", info_commands::InfoCommand::Jobs),
            ("/stats", info_commands::InfoCommand::Stats),
        ] {
            assert_eq!(send(text), UiCommand::Info(expected), "{text}");
        }
        assert_eq!(
            send("/plan-review"),
            UiCommand::Plan {
                action: String::from("review")
            }
        );
        assert_eq!(
            send("/rename release prep"),
            UiCommand::SetName(String::from("release prep"))
        );
        assert_eq!(send("/fresh"), UiCommand::Fresh);
        assert_eq!(send("/retry"), UiCommand::Retry);
        assert_eq!(send("/shake"), UiCommand::Shake);
        assert_eq!(
            send("/template"),
            UiCommand::Info(info_commands::InfoCommand::Templates)
        );
        assert_eq!(
            send("/template fix src/a.rs"),
            UiCommand::ExtensionCommand {
                name: String::from("fix"),
                args: String::from("src/a.rs")
            }
        );
        assert_eq!(send("/compact shake"), UiCommand::Shake);
        assert_eq!(
            send("/checkpoint before-refactor risky part"),
            UiCommand::Checkpoint {
                args: String::from("before-refactor risky part")
            }
        );
        assert_eq!(
            send("/rewind"),
            UiCommand::Rewind {
                name: String::new()
            }
        );
        assert_eq!(
            send("/commit --dry-run"),
            UiCommand::Workspace {
                command: workspace_commands::WorkspaceCommand::Commit,
                args: String::from("--dry-run")
            }
        );
        assert_eq!(
            send("/advisor"),
            UiCommand::Workspace {
                command: workspace_commands::WorkspaceCommand::Advisor,
                args: String::new()
            }
        );
        // The classic aliases `/cp` and `/scoped` used to answer "is a pi
        // command that this stack does not implement yet".
        assert_eq!(send("/cp cmd"), UiCommand::CopyLastCommand);
        assert_eq!(
            send("/scoped anthropic/*"),
            UiCommand::ScopedModels {
                args: String::from("anthropic/*")
            }
        );
        assert_eq!(
            send("/toolsy"),
            UiCommand::ExtensionCommand {
                name: String::from("toolsy"),
                args: String::new()
            },
            "a near-miss token is an extension command, not /tools"
        );
    }

    /// `/fork` existed only on the classic stack. It routes to the driver, and
    /// the selected message the driver hands back lands in the editor only
    /// for the session on screen.
    #[test]
    fn slash_fork_routes_and_the_selected_text_returns_to_the_editor() {
        let (_agent_tx, rx) = mpsc::channel();
        let (submit_tx, submit_rx) = mpsc::channel::<UiCommand>();
        let model = PiFtuiModel::new(rx).with_submit_channel(submit_tx);
        let mut sim = ProgramSimulator::new(model);
        sim.init();
        type_str(&mut sim, "/fork 2");
        sim.inject_event(key(KeyCode::Enter, Modifiers::empty()));
        assert_eq!(
            submit_rx.try_recv().expect("fork routed"),
            UiCommand::Fork {
                args: String::from("2")
            }
        );

        sim.send(PiFtuiMsg::Agent(PiMsg::ConversationReset {
            session_id: String::from("forked"),
            messages: Vec::new(),
            usage: crate::model::Usage::default(),
            status: None,
        }));
        sim.send(PiFtuiMsg::Agent(PiMsg::SetEditorText {
            owner_session_id: String::from("some-other-session"),
            text: String::from("stale"),
        }));
        assert_eq!(sim.model().input.text(), "", "a stale hand-back is dropped");
        sim.send(PiFtuiMsg::Agent(PiMsg::SetEditorText {
            owner_session_id: String::from("forked"),
            text: String::from("reword me"),
        }));
        assert_eq!(sim.model().input.text(), "reword me");
    }

    #[test]
    fn returned_control_input_preserves_draft_and_ignores_stale_sessions() {
        let (_unused, model) = new_model();
        let mut sim = ProgramSimulator::new(model);
        sim.init();
        sim.send(PiFtuiMsg::Agent(PiMsg::ConversationReset {
            session_id: String::from("current"),
            messages: Vec::new(),
            usage: crate::model::Usage::default(),
            status: None,
        }));
        type_str(&mut sim, "existing draft");
        sim.send(PiFtuiMsg::Agent(PiMsg::RestorePendingInput {
            owner_session_id: String::from("previous"),
            text: String::from("stale controls"),
        }));
        assert_eq!(
            // ubs:ignore[rust.panic.assert-macros] -- Regression oracle.
            sim.model().input.text(),
            "existing draft"
        );
        sim.send(PiFtuiMsg::Agent(PiMsg::RestorePendingInput {
            owner_session_id: String::from("current"),
            text: String::from("first control\n\nsecond control"),
        }));
        sim.send(PiFtuiMsg::Agent(PiMsg::RestorePendingInput {
            owner_session_id: String::from("current"),
            text: String::new(),
        }));
        assert_eq!(
            // ubs:ignore[rust.panic.assert-macros] -- Regression oracle.
            sim.model().input.text(),
            "first control\n\nsecond control\n\nexisting draft"
        );
        sim.send(PiFtuiMsg::Agent(PiMsg::SetEditorText {
            owner_session_id: String::from("current"),
            text: String::from("explicit replacement"),
        }));
        assert_eq!(
            // ubs:ignore[rust.panic.assert-macros] -- Regression oracle.
            sim.model().input.text(),
            "explicit replacement"
        );
    }

    fn returned_input(owner: &str, text: &str) -> PiFtuiMsg {
        PiFtuiMsg::Agent(PiMsg::RestorePendingInput {
            owner_session_id: owner.to_string(),
            text: text.to_string(),
        })
    }

    #[test]
    fn returned_prompts_wait_for_card_bursts_without_changing_answers_or_recall() {
        for first_card in ["ask", "extension"] {
            let mut sim = recalled_prompt_sim("saved\nprompt", KeyBindings::default());
            sim.model_mut().displayed_session_id = Some(String::from("current"));
            if first_card == "ask" {
                sim.send(PiFtuiMsg::Agent(PiMsg::AskUiRequest(ask_request(
                    "first",
                    vec![question("Choose?", &["A", "B"], false)],
                ))));
            } else {
                sim.send(PiFtuiMsg::Agent(PiMsg::ExtensionUiRequest(ext_request(
                    "first",
                    "input",
                    serde_json::json!({"title": "First answer"}),
                ))));
            }
            sim.send(PiFtuiMsg::Agent(PiMsg::ExtensionUiRequest(ext_request(
                "successor",
                "input",
                serde_json::json!({"title": "Next answer"}),
            ))));
            sim.inject_event(Event::Paste(ftui::PasteEvent::new("partial\nanswer", true)));
            sim.inject_event(key(KeyCode::Left, Modifiers::SHIFT));
            let cursor = sim.model().input.cursor();
            let selection = sim.model().input.selected_text();
            let undo_ops = sim.model().input.undo_op_count();
            sim.send(returned_input("current", "first\nreturn"));
            sim.send(returned_input("current", "second return"));
            assert_eq!(sim.model().input.text(), "partial\nanswer");
            assert_eq!(sim.model().input.cursor(), cursor);
            assert_eq!(sim.model().input.selected_text(), selection);
            assert_eq!(sim.model().input.undo_op_count(), undo_ops);
            assert_eq!(sim.model().history_cursor, Some(1));
            assert_eq!(sim.model().pending_input_restores.len(), 2);

            sim.inject_event(key(KeyCode::Escape, Modifiers::empty()));
            assert_eq!(
                sim.model()
                    .active_ext
                    .as_ref()
                    .map(|request| request.id.as_str()),
                Some("successor")
            );
            assert!(sim.model().input.is_empty());
            assert_eq!(sim.model().pending_input_restores.len(), 2);
            type_str(&mut sim, "next answer");
            sim.inject_event(key(KeyCode::Escape, Modifiers::empty()));
            let expected = "first\nreturn\n\nsecond return\n\nsaved\nprompt";
            assert_eq!(sim.model().input.text(), expected);
            assert!(sim.model().card_draft_snapshot.is_none());
            assert!(sim.model().pending_input_restores.is_empty());
            assert_eq!(sim.model().history_cursor, None);
            sim.inject_event(Event::Tick);
            assert_eq!(sim.model().input.text(), expected, "restore only once");
        }
    }

    #[test]
    fn returned_prompts_wait_through_other_modal_and_inactive_owners() {
        for owner in ["settings", "custom", "suspending", "working"] {
            let (_tx, mut model) = new_model();
            let (submit_tx, _submit_rx) = mpsc::channel();
            model.displayed_session_id = Some(String::from("current"));
            model.input.set_text("saved\ndraft");
            let mut sim = ProgramSimulator::new(model.with_submit_channel(submit_tx));
            sim.init();
            sim.inject_event(key(KeyCode::Left, Modifiers::SHIFT));
            match owner {
                "settings" => sim.inject_event(key(KeyCode::F(2), Modifiers::empty())),
                "custom" => send_ui_effect(
                    &mut sim,
                    "setWidget",
                    serde_json::json!({
                        "widgetKey": EXT_CUSTOM_OVERLAY_KEY,
                        "lines": ["modal"],
                    }),
                ),
                "suspending" => sim.model_mut().suspending = true,
                _ => sim.send(PiFtuiMsg::Agent(PiMsg::AgentStart)),
            }
            let cursor = sim.model().input.cursor();
            let selection = sim.model().input.selected_text();
            sim.send(returned_input("current", "first"));
            sim.send(returned_input("current", "second"));
            sim.send(returned_input("current", ""));
            assert_eq!(sim.model().input.text(), "saved\ndraft", "{owner}");
            assert_eq!(sim.model().input.cursor(), cursor, "{owner}");
            assert_eq!(sim.model().input.selected_text(), selection, "{owner}");
            assert_eq!(sim.model().pending_input_restores.len(), 2, "{owner}");
            match owner {
                "settings" => {
                    assert!(sim.model().settings_pending);
                    sim.send(PiFtuiMsg::Agent(PiMsg::Settings {
                        snapshot: settings_snapshot_fixture(),
                        changed: None,
                    }));
                    assert!(sim.model().picker.is_some());
                    assert_eq!(sim.model().pending_input_restores.len(), 2);
                    sim.inject_event(key(KeyCode::Escape, Modifiers::empty()));
                }
                "custom" => send_ui_effect(
                    &mut sim,
                    "setWidget",
                    serde_json::json!({"widgetKey": EXT_CUSTOM_OVERLAY_KEY, "clear": true}),
                ),
                "suspending" => sim.send(PiFtuiMsg::Resumed),
                _ => sim.send(PiFtuiMsg::Agent(PiMsg::AgentDone {
                    usage: None,
                    stop_reason: StopReason::Stop,
                    error_message: None,
                })),
            }
            assert_eq!(
                sim.model().input.text(),
                "first\n\nsecond\n\nsaved\ndraft",
                "{owner}"
            );
            assert!(sim.model().pending_input_restores.is_empty(), "{owner}");
        }
    }

    #[test]
    fn returned_prompts_wait_until_login_secret_is_submitted_and_login_settles() {
        let (_tx, mut model) = new_model();
        let (submit_tx, submit_rx) = mpsc::channel();
        model.displayed_session_id = Some(String::from("current"));
        let mut sim = ProgramSimulator::new(model.with_submit_channel(submit_tx));
        sim.init();
        sim.send(PiFtuiMsg::Agent(PiMsg::LoginPending {
            provider: Some(String::from("openai")),
            accepts_empty_input: false,
        }));
        type_str(&mut sim, "private-code");
        sim.inject_event(key(KeyCode::Left, Modifiers::SHIFT));
        let cursor = sim.model().input.cursor();
        sim.send(returned_input("current", "first"));
        sim.send(returned_input("current", "second"));
        assert_eq!(sim.model().input.text(), "private-code");
        assert_eq!(sim.model().input.cursor(), cursor);
        assert_eq!(sim.model().input.selected_text().as_deref(), Some("e"));

        sim.inject_event(key(KeyCode::Enter, Modifiers::empty()));
        assert!(matches!(
            submit_rx.try_recv().expect("login reply"),
            UiCommand::LoginSubmit(secret) if secret.0 == "private-code"
        ));
        assert!(sim.model().input.is_empty());
        assert_eq!(sim.model().pending_input_restores.len(), 2);
        sim.send(PiFtuiMsg::Agent(PiMsg::LoginPending {
            provider: None,
            accepts_empty_input: false,
        }));
        assert_eq!(sim.model().input.text(), "first\n\nsecond");
        assert!(sim.model().pending_input_restores.is_empty());
        sim.inject_event(key(KeyCode::Enter, Modifiers::empty()));
        assert_eq!(
            submit_rx.try_recv().expect("restored ordinary prompt"),
            UiCommand::Prompt(String::from("first\n\nsecond"))
        );
    }

    #[test]
    fn session_replacement_discards_deferred_returns_before_modal_release() {
        for retry in [false, true] {
            let (_tx, mut model) = new_model();
            model.displayed_session_id = Some(String::from("old"));
            model.input.set_text("old draft");
            let mut sim = ProgramSimulator::new(model);
            sim.init();
            send_ui_effect(
                &mut sim,
                "setWidget",
                serde_json::json!({
                    "widgetKey": EXT_CUSTOM_OVERLAY_KEY,
                    "lines": ["modal"],
                }),
            );
            sim.send(returned_input("old", "old return"));
            assert_eq!(sim.model().pending_input_restores.len(), 1);
            let reset = if retry {
                PiMsg::RetryCommitted {
                    session_id: String::from("new"),
                    messages: Vec::new(),
                    usage: crate::model::Usage::default(),
                    status: None,
                    text: String::from("retried prompt"),
                }
            } else {
                PiMsg::ConversationReset {
                    session_id: String::from("new"),
                    messages: Vec::new(),
                    usage: crate::model::Usage::default(),
                    status: None,
                }
            };
            sim.send(PiFtuiMsg::Agent(reset));
            assert!(sim.model().custom_overlay_open());
            assert!(sim.model().pending_input_restores.is_empty());
            sim.send(PiFtuiMsg::Agent(PiMsg::SetEditorText {
                owner_session_id: String::from("new"),
                text: String::from("new draft"),
            }));
            sim.send(returned_input("old", "late old return"));
            assert!(sim.model().pending_input_restores.is_empty());
            sim.send(returned_input("new", "new return"));
            assert_eq!(sim.model().input.text(), "new draft");
            send_ui_effect(
                &mut sim,
                "setWidget",
                serde_json::json!({"widgetKey": EXT_CUSTOM_OVERLAY_KEY, "clear": true}),
            );
            assert_eq!(sim.model().input.text(), "new return\n\nnew draft");
            assert!(sim.model().pending_input_restores.is_empty());
        }
    }

    #[test]
    fn expired_ask_flushes_returned_prompts_before_dropping_its_input_event() {
        for event in [
            key(KeyCode::Enter, Modifiers::empty()),
            Event::Paste(ftui::PasteEvent::new("must not reach the draft", true)),
            mouse(MouseEventKind::Down(MouseButton::Left), 0, 0),
        ] {
            let (_tx, rx) = mpsc::channel();
            let (submit_tx, submit_rx) = mpsc::channel();
            let tool = crate::ask::AskTool::new(crate::ask::AskPolicy::Error);
            tool.register_channel_ui_request_for_tests("expired-restore");
            let current = Arc::new(Mutex::new(Some(tool.clone())));
            let mut model = PiFtuiModel::new(rx)
                .with_current_ask(current)
                .with_submit_channel(submit_tx);
            model.displayed_session_id = Some(String::from("current"));
            model.input.set_text("saved draft");
            let mut sim = ProgramSimulator::new(model);
            sim.init();
            sim.send(PiFtuiMsg::Agent(PiMsg::AskUiRequest(ask_request(
                "expired-restore",
                vec![question("Choose?", &["A", "B"], false)],
            ))));
            type_str(&mut sim, "unfinished answer");
            sim.send(returned_input("current", "returned prompt"));
            tool.respond_ui(
                "expired-restore",
                AskResponse {
                    answers: Vec::new(),
                    dismissed: true,
                },
            );
            sim.inject_event(event);
            assert!(sim.model().active_ask.is_none());
            assert_eq!(
                sim.model().input.text(),
                "returned prompt\n\nsaved draft"
            );
            assert!(sim.model().pending_input_restores.is_empty());
            assert!(submit_rx.try_recv().is_err());
        }
    }

    #[test]
    fn restored_prompts_preserve_whitespace_and_refresh_completion_only_when_applied() {
        for (returned, draft, completion) in [
            ("returned", "", false),
            ("returned", " \n\t", false),
            ("returned", "/he", false),
            ("/he", "", true),
        ] {
            let (_tx, mut model) = new_model();
            model.input.set_text(draft);
            model.maybe_trigger_autocomplete();
            model.suspending = true;
            let mut sim = ProgramSimulator::new(model);
            sim.init();
            sim.send(returned_input("current", returned));
            assert_eq!(sim.model().input.text(), draft);
            assert!(!sim.model().completion_visible());
            assert!(!sim.model().autocomplete.open);
            sim.send(PiFtuiMsg::Resumed);
            let expected = if draft.is_empty() {
                returned.to_string()
            } else {
                format!("{returned}\n\n{draft}")
            };
            assert_eq!(sim.model().input.text(), expected);
            assert_eq!(sim.model().completion_visible(), completion);
            assert!(sim.model().pending_input_restores.is_empty());
        }
    }

    /// The fork keeps everything before the selected user message, drops that
    /// message and what followed, and returns its text for the editor.
    #[test]
    fn build_fork_session_branches_before_the_selected_message() {
        use crate::model::UserContent;
        use crate::session::{Session, SessionMessage};

        let dir = tempfile::tempdir().expect("tempdir");
        let mut source = Session::create_with_dir(Some(dir.path().to_path_buf()));
        source.header.thinking_level = Some(String::from("high"));
        for text in ["first question", "second question"] {
            source.append_message(SessionMessage::User {
                content: UserContent::Text(text.to_string()),
                timestamp: Some(0),
            });
        }
        source.ensure_entry_ids();
        let candidates = crate::interactive::fork_candidates(&source);
        assert_eq!(candidates.len(), 2);
        let second = crate::interactive::select_fork_candidate(&candidates, "2").expect("select");

        let (forked, selected_text) = build_fork_session(
            &source,
            &second.id,
            String::from("anthropic"),
            String::from("claude-test"),
        )
        .expect("build fork");
        assert_eq!(selected_text, "second question");
        let texts = forked
            .to_messages_for_current_path()
            .iter()
            .filter_map(|message| match message {
                crate::model::Message::User(user) => match &user.content {
                    UserContent::Text(text) => Some(text.clone()),
                    UserContent::Blocks(_) => None,
                },
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(texts, vec![String::from("first question")]);
        assert_ne!(forked.header.id, source.header.id);
        assert_eq!(forked.header.provider.as_deref(), Some("anthropic"));
        assert_eq!(forked.header.model_id.as_deref(), Some("claude-test"));
        assert_eq!(forked.header.thinking_level.as_deref(), Some("high"));
        assert_eq!(forked.session_dir.as_deref(), Some(dir.path()));
    }

    #[test]
    #[allow(clippy::too_many_lines)]
    fn ftui_fork_recovers_late_billing_after_reload_and_all_foreground_handles_close() {
        use crate::model::UserContent;
        use crate::session::SessionMessage;

        let cwd = tempfile::tempdir().expect("cwd");
        let sessions = tempfile::tempdir().expect("sessions");
        let reactor = asupersync::runtime::reactor::create_reactor().expect("reactor");
        let runtime = asupersync::runtime::RuntimeBuilder::current_thread()
            .with_reactor(reactor)
            .build()
            .expect("runtime");
        let runtime_handle = runtime.handle();
        let (agent_tx, agent_rx) = mpsc::channel();
        let ext_handler = Arc::new(FtuiExtensionUiHandler::new(agent_tx.clone()));
        let current_ask: CurrentAsk = Arc::default();
        let template = resume_template_from(&crate::sdk::SessionOptions {
            provider: Some(String::from("openai")),
            model: Some(String::from("gpt-4o")),
            api_key: Some(String::from("ftui-fork-cost-test-key")),
            working_directory: Some(cwd.path().to_path_buf()),
            workspace_trusted: true,
            session_dir: Some(sessions.path().to_path_buf()),
            enabled_tools: Some(Vec::new()),
            no_context_files: true,
            max_cost: Some(2.0),
            ..crate::sdk::SessionOptions::default()
        });

        runtime.block_on(Box::pin(async {
            let mut handle = crate::sdk::create_agent_session_deferred_mcp(replacement_options(
                &template,
                &ext_handler,
                &runtime_handle,
            ))
            .await
            .expect("source session");
            let budget = handle.session().agent.cost_budget().unwrap().clone();
            budget.record(0.25).unwrap();
            let mut outstanding = budget.start_attempt().unwrap();
            outstanding.observe(0.5).unwrap();
            let (source_id, source_path) = {
                let store = handle.session_store();
                let cx = crate::agent_cx::AgentCx::for_request();
                let mut session = store.lock(cx.cx()).await.unwrap();
                for text in ["keep this context", "revise this request"] {
                    session.append_message(SessionMessage::User {
                        content: UserContent::Text(text.to_string()),
                        timestamp: Some(0),
                    });
                }
                session.save().await.unwrap();
                (session.header.id.clone(), session.path.clone().unwrap())
            };

            // A same-file reload must accept its prospective self-reference
            // without retiring the account or losing the outstanding attempt.
            reload_session_command(
                &template,
                &mut handle,
                &current_ask,
                &ext_handler,
                &agent_tx,
                &runtime_handle,
            )
            .await
            .expect("reload before fork");
            assert_eq!(
                handle
                    .with_session(|session| session.header.id.clone())
                    .await
                    .unwrap(),
                source_id
            );
            assert!(
                handle
                    .session()
                    .agent
                    .cost_budget()
                    .unwrap()
                    .same_tree(&budget)
            );
            let after_reload = budget.snapshot();
            assert!((after_reload.spent - 0.25).abs() < f64::EPSILON);
            assert!((after_reload.pending - 0.5).abs() < f64::EPSILON);
            assert!(agent_rx.try_iter().any(|event| matches!(event,
                PiMsg::System(text) if text.starts_with("Reloaded"))));

            asupersync::time::timeout(
                asupersync::time::wall_now(),
                Duration::from_secs(30),
                Box::pin(fork_session_command(
                    "2",
                    &template,
                    &mut handle,
                    &current_ask,
                    &ext_handler,
                    &agent_tx,
                    &runtime_handle,
                )),
            )
            .await
            .expect("fork must not reacquire the prepared source store")
            .expect("FTUI fork command");
            let (fork_id, fork_path, messages) = handle
                .with_session(|session| {
                    (
                        session.header.id.clone(),
                        session.path.clone().unwrap(),
                        session.to_messages_for_current_path(),
                    )
                })
                .await
                .unwrap();
            assert_ne!(fork_id, source_id);
            assert_ne!(fork_path, source_path);
            assert!(
                handle
                    .session()
                    .agent
                    .cost_budget()
                    .unwrap()
                    .same_tree(&budget)
            );
            let after_fork = budget.snapshot();
            assert!((after_fork.spent - 0.25).abs() < f64::EPSILON);
            assert!((after_fork.pending - 0.5).abs() < f64::EPSILON);
            assert!(
                matches!(messages.as_slice(), [crate::model::Message::User(user)]
                if matches!(&user.content, UserContent::Text(text) if text == "keep this context"))
            );
            assert!(agent_rx.try_iter().any(|event| matches!(event,
                PiMsg::SetEditorText { owner_session_id, text }
                    if owner_session_id == fork_id && text == "revise this request")));
            assert!(handle.shutdown_owned_resources().await.completed_cleanly());
            let source_bytes = std::fs::read(&source_path).unwrap();
            let fork_bytes = std::fs::read(&fork_path).unwrap();
            drop(budget);

            // The captured request remains after both foreground handles have
            // closed. Its final bill must reach disk without either handle.
            outstanding.finish(1.75).unwrap();
            drop(outstanding);
            assert_eq!(std::fs::read(&source_path).unwrap(), source_bytes);
            assert_eq!(std::fs::read(&fork_path).unwrap(), fork_bytes);

            let mut cold_options = replacement_options(&template, &ext_handler, &runtime_handle);
            assert!(cold_options.cost_budget.is_none());
            cold_options.session_path = Some(fork_path);
            let cold = crate::sdk::create_agent_session_deferred_mcp(cold_options)
                .await
                .expect("cold resume after late billing");
            let recovered = cold.session().agent.cost_budget().unwrap();
            assert!((recovered.spent() - 2.0).abs() < f64::EPSILON);
            assert!(
                matches!(recovered.admit(), Err(crate::error::Error::CostCap { spent, cap })
                if (spent - 2.0).abs() < f64::EPSILON && (cap - 2.0).abs() < f64::EPSILON)
            );
            assert!(cold.shutdown_owned_resources().await.completed_cleanly());
        }));
    }

    #[test]
    fn ftui_fork_preserves_a_lazy_sources_workspace_and_resumed_sdk_context() {
        let temp = tempfile::tempdir().expect("tempdir");
        let reactor = asupersync::runtime::reactor::create_reactor().expect("reactor");
        let runtime = asupersync::runtime::RuntimeBuilder::current_thread()
            .with_reactor(reactor)
            .build()
            .expect("runtime");
        runtime.block_on(Box::pin(async {
            let fixture = crate::session::fork_tests::workspace_fixture(temp.path(), true).await;
            let (mut fork, selected_text) = build_fork_session(
                &fixture.source,
                &fixture.target_id,
                "anthropic".to_string(),
                "test-model".to_string(),
            )
            .expect("build FTUI fork");
            assert_eq!(selected_text, "revise this request");
            fixture.assert_workspace(&fork);
            fixture.assert_selected_context(&fork);
            fork.save().await.expect("persist FTUI fork");
            let mut workspace = crate::workspace::WorkspaceHandle::single(&fixture.bound_cwd);
            workspace.add_root(&fixture.additional_root);
            let options = crate::sdk::SessionOptions {
                provider: Some("openai".to_string()),
                model: Some("gpt-4o".to_string()),
                api_key: Some("fork-workspace-test-key".to_string()),
                session_path: fork.path.clone(),
                working_directory: Some(fixture.bound_cwd.clone()),
                workspace: Some(workspace),
                workspace_trusted: true,
                enabled_tools: Some(vec!["write".to_string()]),
                ..crate::sdk::SessionOptions::default()
            };
            let handle = crate::sdk::create_agent_session(options)
                .await
                .expect("resume FTUI fork in its attached workspace");
            assert!(
                handle
                    .session()
                    .agent
                    .system_prompt()
                    .unwrap()
                    .contains(crate::session::fork_tests::WORKSPACE_CONTEXT)
            );
            let tools = handle.session().agent.shared_tools().snapshot();
            let output = tools
                .get("write")
                .expect("write tool")
                .execute(
                    "fork-workspace-write",
                    serde_json::json!({"path": "fork-continuation.txt", "content": "continued fork"}),
                    None,
                )
                .await
                .expect("write from resumed fork");
            assert!(!output.is_error);
            assert_eq!(
                std::fs::read_to_string(fixture.bound_cwd.join("fork-continuation.txt"))
                    .expect("fork output in bound workspace"),
                "continued fork"
            );
            assert!(!fixture.original_cwd.exists());
            assert!(handle.shutdown_owned_resources().await.completed_cleanly());
            assert_eq!(
                std::fs::read(&fixture.source_file).expect("unchanged source"),
                fixture.source_bytes
            );
        }));
    }

    /// While a login waits for input, the next line is the secret: it goes to
    /// the driver and never into the transcript. A slash command abandons the
    /// prompt and runs normally.
    #[test]
    fn pending_login_input_reaches_the_driver_without_being_echoed() {
        let (_agent_tx, rx) = mpsc::channel();
        let (submit_tx, submit_rx) = mpsc::channel::<UiCommand>();
        let model = PiFtuiModel::new(rx).with_submit_channel(submit_tx);
        let mut sim = ProgramSimulator::new(model);
        sim.init();
        sim.send(PiFtuiMsg::Agent(PiMsg::LoginPending {
            provider: Some(String::from("openai")),
            accepts_empty_input: false,
        }));

        // A bare Enter is not an API key; nothing is sent.
        sim.inject_event(key(KeyCode::Enter, Modifiers::empty()));
        assert!(
            submit_rx.try_recv().is_err(),
            "an empty line must not submit"
        );

        type_str(&mut sim, "sk-very-secret");
        sim.inject_event(key(KeyCode::Enter, Modifiers::empty()));
        assert_eq!(
            submit_rx.try_recv().expect("login input routed"),
            UiCommand::LoginSubmit(LoginInput(String::from("sk-very-secret")))
        );
        assert!(
            sim.model()
                .transcript
                .iter()
                .all(|entry| !entry.text.contains("sk-very-secret")),
            "the key must never be echoed"
        );
        assert!(
            format!(
                "{:?}",
                UiCommand::LoginSubmit(LoginInput(String::from("sk-very-secret")))
            )
            .contains("<redacted>"),
            "Debug must not print the key"
        );

        // The driver keeps the prompt armed until it says otherwise; a slash
        // command abandons it and routes as a command.
        type_str(&mut sim, "/session");
        sim.inject_event(key(KeyCode::Enter, Modifiers::empty()));
        assert_eq!(
            submit_rx.try_recv().expect("slash command routed"),
            UiCommand::SessionInfo
        );
        assert!(sim.model().login_pending.is_none());
        type_str(&mut sim, "hello");
        sim.inject_event(key(KeyCode::Enter, Modifiers::empty()));
        assert_eq!(
            submit_rx.try_recv().expect("prompt routed"),
            UiCommand::Prompt(String::from("hello")),
            "after cancelling, input is an ordinary prompt again"
        );
    }

    /// The planted negative, and the one that matters most: `/share public` is
    /// asking for the opposite of what this does. It must be refused in the UI,
    /// BEFORE anything reaches the driver — so the safe answer never depends on
    /// the driver, the `gh` subprocess, or the network.
    #[test]
    fn slash_share_refuses_an_argument_without_reaching_the_driver() {
        let (_agent_tx, rx) = mpsc::channel();
        let (submit_tx, submit_rx) = mpsc::channel::<UiCommand>();
        let model = PiFtuiModel::new(rx).with_submit_channel(submit_tx);
        let mut sim = ProgramSimulator::new(model);
        sim.init();
        type_str(&mut sim, "/share public");
        sim.inject_event(key(KeyCode::Enter, Modifiers::empty()));
        assert!(
            submit_rx.try_recv().is_err(),
            "/share public must never reach the driver"
        );
        assert!(
            sim.model()
                .transcript
                .iter()
                .any(|e| e.text.contains("public sharing is disabled")),
            "the refusal must say why"
        );
    }

